$q=db()->prepare("SELECT m.* FROM orders o JOIN services s ON s.id=o.service_id JOIN template_assets a ON a.service_id=s.id JOIN customer_media m ON m.id=a.source_media_id WHERE o.id=? AND o.user_id=? AND o.status NOT IN ('rejected','cancelled') AND EXISTS(SELECT 1 FROM wallet_ledger l WHERE l.user_id=o.user_id AND l.reference=CONCAT('order:',o.id) AND l.kind='debit' AND l.status='posted')");$q->execute([(int)($_GET['order']??0),$u['id']]);$m=$q->fetch();if(!$m)json_out(['error'=>'No paid template download for this account.'],404);
